package com.motionlayer.editor
import androidx.compose.foundation.background; import androidx.compose.foundation.layout.*; import androidx.compose.material3.*; import androidx.compose.runtime.*; import androidx.compose.ui.Modifier; import androidx.compose.ui.graphics.Color; import androidx.compose.ui.unit.dp
@Composable fun EditorScreen(vm:EditorViewModel,onExport:()->Unit){ val project by vm.project.collectAsState(); val time by vm.timeMs.collectAsState(); val selected by vm.selectedLayerId.collectAsState(); val selectedLayer=project.layers.find{it.id==selected}; Scaffold(containerColor=Color(0xff101010), topBar={ Row(Modifier.fillMaxWidth().padding(12.dp), horizontalArrangement=Arrangement.SpaceBetween){ Text("MotionLayer", color=Color.White); Row{ Button(onClick={vm.saveProject()}){Text("Save")}; Spacer(Modifier.width(8.dp)); Button(onClick=onExport){Text("Export")} } } }){ pad-> Column(Modifier.padding(pad).fillMaxSize()){ PreviewCanvas(project,time,Modifier.weight(1f).fillMaxWidth()); LayerPanel(vm); PropertyPanel(selectedLayer,vm); TimelineView(project,time,{vm.timeMs.value=it},{vm.selectedLayerId.value=it}) } } }
